// Calcula el primer y último día del mes anterior en la zona horaria configurada (Europe/Madrid).
const tz = ($vars && $vars.ZONA_HORARIA) ? $vars.ZONA_HORARIA : 'Europe/Madrid';
const hoy = $now.setZone(tz);
const anterior = hoy.minus({ months: 1 });
const desde = anterior.startOf('month').toFormat('yyyy-MM-dd');
const hasta = anterior.endOf('month').toFormat('yyyy-MM-dd');
const mes = anterior.toFormat('yyyy-MM');
return [{ json: { desde, hasta, mes, zona: tz } }];

// Emite un item por cada apartado con estado = liquidado.
const salida = [];
for (const item of ($('Pedir todos los apartados') && $('Pedir todos los apartados').all()) ? $('Pedir todos los apartados').all() : []) {
  const a = item.json;
  if (a && a.estado === 'liquidado' && a.id !== undefined) {
    salida.push({ json: a });
  }
}
if (salida.length === 0) {
  salida.push({ json: { id: null, _dummy: true } });
}
return salida;

// Agrega ventas, abonos, pendiente de activos, nuevos (por fecha), liquidados (por ultimo abono) y vencidos (por vale).
// Solo redondea los totales a 2 decimales; los sumandos no se alteran (ADR-0002, D6).
const calc = $('Calcular mes anterior').first().json;
const desde = calc.desde;
const hasta = calc.hasta;
const mes = calc.mes;

const enMes = (f) => typeof f === 'string' && f >= desde && f <= hasta;

const ventasItems = $('Pedir ventas del mes').all()
  .map((i) => i.json)
  .filter((v) => v && v.importe !== undefined && v.fecha);
const abonosItems = $('Pedir abonos del mes').all()
  .map((i) => i.json)
  .filter((a) => a && a.importe !== undefined && a.fecha);
const activosItems = $('Pedir apartados activos').all()
  .map((i) => i.json)
  .filter((a) => a && a.pendiente !== undefined);
const todosItems = $('Pedir todos los apartados').all()
  .map((i) => i.json)
  .filter((a) => a && a.id !== undefined && a.fecha);
const valesItems = $('Pedir vales').all()
  .map((i) => i.json)
  .filter((v) => v && v.fecha);

const detalleItems = $input.all().map((i) => i.json);

const round2 = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;

const rawVentas = ventasItems.reduce((s, v) => s + Number(v.importe), 0);
const rawAbonos = abonosItems.reduce((s, a) => s + Number(a.importe), 0);
const rawPendiente = activosItems.reduce((s, a) => s + Number(a.pendiente), 0);

const totalVentas = round2(rawVentas);
const totalAbonos = round2(rawAbonos);
const totalRecaudacion = round2(rawVentas + rawAbonos);
const pendienteTotal = round2(rawPendiente);

const nuevos = todosItems.filter((a) => enMes(a.fecha)).length;

const vencidosIds = new Set();
for (const v of valesItems) {
  if (enMes(v.fecha) && v.apartado_id !== undefined) {
    vencidosIds.add(v.apartado_id);
  }
}
const vencidos = vencidosIds.size;

let liquidados = 0;
const avisos = [];
for (const d of detalleItems) {
  if (!d || typeof d !== 'object') continue;
  if (d._dummy || d.id === null || d.id === undefined) continue;
  if (d.error || (typeof d.statusCode === 'number' && d.statusCode >= 400)) {
    const det = (d.error && d.error.response && d.error.response.body && d.error.response.body.detail)
      || d.detail || d.message || 'detalle inaccesible';
    avisos.push('Apartado ' + (d.id || '?') + ': ' + det);
    continue;
  }
  if (d.id === undefined && d.abonos === undefined) continue;
  const abonos = Array.isArray(d.abonos) ? d.abonos : [];
  if (abonos.length === 0) continue;
  const fechas = abonos.map((a) => a.fecha).filter(Boolean);
  if (fechas.length === 0) continue;
  const ultimo = fechas.reduce((max, f) => (f > max ? f : max), fechas[0]);
  if (enMes(ultimo)) liquidados += 1;
}

const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const partes = mes.split('-');
const mesNombre = MESES[parseInt(partes[1], 10) - 1] + ' ' + partes[0];

const fmt = (n) => new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' }).format(n);

const sinMovimientos = (ventasItems.length === 0 && abonosItems.length === 0 && nuevos === 0 && liquidados === 0 && vencidos === 0);
const notaSinMov = sinMovimientos ? '<p>Sin movimientos en el mes.</p>' : '';
const notaAvisos = avisos.length ? '<p><strong>Avisos:</strong> ' + avisos.join('; ') + '</p>' : '';

const cuerpo = [
  '<h2>Informe mensual · ' + mesNombre + '</h2>',
  '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">',
  '  <tr><th>Concepto</th><th>Valor</th></tr>',
  '  <tr><td>Recaudación ventas directas</td><td>' + fmt(totalVentas) + '</td></tr>',
  '  <tr><td>Recaudación abonos</td><td>' + fmt(totalAbonos) + '</td></tr>',
  '  <tr><td>Recaudación total</td><td>' + fmt(totalRecaudacion) + '</td></tr>',
  '  <tr><td>Pendiente de cobro</td><td>' + fmt(pendienteTotal) + '</td></tr>',
  '  <tr><td>Apartados nuevos</td><td>' + nuevos + '</td></tr>',
  '  <tr><td>Apartados liquidados</td><td>' + liquidados + '</td></tr>',
  '  <tr><td>Apartados vencidos</td><td>' + vencidos + '</td></tr>',
  '</table>',
  notaSinMov,
  notaAvisos,
].filter(Boolean).join('\n');

return [{
  json: {
    mes,
    mes_nombre: mesNombre,
    recaudacion_ventas: totalVentas,
    recaudacion_abonos: totalAbonos,
    recaudacion_total: totalRecaudacion,
    pendiente_total: pendienteTotal,
    apartados_nuevos: nuevos,
    apartados_liquidados: liquidados,
    apartados_vencidos: vencidos,
    avisos,
    asunto_correo: 'Informe mensual · ' + mesNombre,
    cuerpo_correo: cuerpo,
  }
}];
